    delete cleaned.correct_answer;
    delete cleaned.audioScript;
    delete cleaned.audio_script;
    delete cleaned.acceptedAnswers;
    delete cleaned.accepted_answers;
    delete cleaned.answerKey;
    delete cleaned.answer_key;
