// server/routes/seasonal.routes.ts
async function seasonalRoutes(fastify) {
  const service = new SeasonalService(fastify.prisma);
  fastify.get("/active", async (request, reply) => {
    try {
      const activeEvent = await service.getActiveEvent();
      return reply.send({
        success: true,
        isActive: !!activeEvent,
        event: activeEvent
      });
    } catch (err) {
      return reply.status(500).send({ error: err.message });
    }
  });
  fastify.get("/my-progress", { preHandler: authenticate }, async (request, reply) => {
    try {
      const studentId = request.user.id;
      const progress = await service.getStudentProgress(studentId);
      return reply.send({
        success: true,
        progress
      });
    } catch (err) {
      return reply.status(500).send({ error: err.message });
    }
  });
  fastify.post(
    "/claim",
    { preHandler: authenticate },
    async (request, reply) => {
      try {
        const studentId = request.user.id;
        const { homeworkId } = request.body || {};
        if (!homeworkId) {
          return reply.status(400).send({ error: "homeworkId l\xE0 b\u1EAFt bu\u1ED9c" });
        }
        const result = await service.claimReward(studentId, homeworkId);
        return reply.status(result.isFirstClaim ? 201 : 200).send({
          success: true,
          ...result
        });
      } catch (err) {
        return reply.status(400).send({ error: err.message });
      }
    }
  );
  fastify.get(
    "/admin/events",
    { preHandler: [authenticate, requireRoles("admin", "superadmin")] },
    async (request, reply) => {
      try {
        const events = await service.getAdminEvents();
        return reply.send({
          success: true,
          events
        });
      } catch (err) {
        return reply.status(500).send({ error: err.message });
      }
    }
  );
  fastify.put(
    "/admin/events/:id",
    { preHandler: [authenticate, requireRoles("admin", "superadmin")] },
    async (request, reply) => {
      try {
        const { id } = request.params;
        const updated = await service.updateEvent(id, request.body);
        return reply.send({
          success: true,
          event: updated
        });
      } catch (err) {
        return reply.status(400).send({ error: err.message });
      }
    }
  );
  fastify.get(
    "/admin/events/:id/payouts",
    { preHandler: [authenticate, requireRoles("admin", "superadmin")] },
    async (request, reply) => {
      try {
        const { id } = request.params;
        const payouts = await service.getPayoutList(id);
        return reply.send({
          success: true,
          payouts
        });
      } catch (err) {
        return reply.status(500).send({ error: err.message });
      }
    }
  );
  fastify.put(
    "/admin/events/:id/payouts/:studentId/disburse",
    { preHandler: [authenticate, requireRoles("admin", "superadmin")] },
    async (request, reply) => {
      try {
        const { id, studentId } = request.params;
        const { isDisbursed } = request.body;
        const result = await service.togglePayoutDisbursed(id, studentId, isDisbursed);
        return reply.send({
          success: true,
          ...result
        });
      } catch (err) {
        return reply.status(400).send({ error: err.message });
      }
    }
  );
  fastify.delete(
    "/admin/events/:id/payouts",
    { preHandler: [authenticate, requireRoles("admin", "superadmin")] },
    async (request, reply) => {
      try {
        const { id } = request.params;
        const result = await service.clearPayoutList(id);
        return reply.send({
          success: true,
          ...result
        });
      } catch (err) {
        return reply.status(500).send({ error: err.message });
      }
    }
  );
}

